package com.lamggm.rospocket;
import android.graphics.*;import android.view.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class CompactCanvasTest {
 @Test public void enlargedFontKeepsAOneByOneGaugeOnSeparatedCompactGeometry()throws Exception{android.content.Context ctx=RuntimeEnvironment.getApplication();android.content.res.Configuration original=new android.content.res.Configuration(ctx.getResources().getConfiguration());android.util.DisplayMetrics old=new android.util.DisplayMetrics();old.setTo(ctx.getResources().getDisplayMetrics());try{android.content.res.Configuration config=new android.content.res.Configuration(original);config.fontScale=1.5f;android.util.DisplayMetrics dm=new android.util.DisplayMetrics();dm.setTo(old);dm.scaledDensity=dm.density*1.5f;ctx.getResources().updateConfiguration(config,dm);UiTheme.save(ctx,"dark");MetricCard c=new MetricCard(ctx);c.display(new DashboardLayout.Display("gauge","data",0,100,"Volts"));c.bind(0,1,"rt/value","std_msgs::msg::dds_::Float64_","Recebendo","50",true);c.sample(new JSONArray().put(new JSONObject().put("path","data").put("value",50).put("state","finite")),true);c.measure(View.MeasureSpec.makeMeasureSpec(294,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(180,View.MeasureSpec.EXACTLY));c.layout(0,0,294,180);Bitmap b=Bitmap.createBitmap(294,180,Bitmap.Config.ARGB_8888);c.draw(new Canvas(b));int intruding=0,valueInk=0;for(int y=120;y<145;y++)for(int x=12;x<282;x++)if(b.getPixel(x,y)==0xff4688d4)intruding++;for(int y=139;y<162;y++)for(int x=12;x<282;x++)if(b.getPixel(x,y)==VisualButton.ink(ctx))valueInk++;assertEquals("Font150% must not select expanded needle geometry in a1x1 card",0,intruding);assertTrue("Enlarged actual value remains visible",valueInk>30);String out=System.getenv("POCKET_GAUGE_PREVIEW_DIR");if(out!=null)try(java.io.OutputStream s=java.nio.file.Files.newOutputStream(java.nio.file.Paths.get(out,"compact-gauge-font150-HOST-SYNTHETIC.png"))){b.compress(Bitmap.CompressFormat.PNG,100,s);}}finally{ctx.getResources().updateConfiguration(original,old);}}
 @Test public void compactGaugeSeparatesNeedleFromItsVisibleValue()throws Exception{android.content.Context ctx=RuntimeEnvironment.getApplication();UiTheme.save(ctx,"dark");MetricCard c=new MetricCard(ctx);c.display(new DashboardLayout.Display("gauge","data",0,100,"V"));c.bind(0,1,"rt/speed","std_msgs::msg::dds_::Float64_","Recebendo","50",true);c.sample(new JSONArray().put(new JSONObject().put("path","data").put("value",50).put("state","finite")),true);c.measure(View.MeasureSpec.makeMeasureSpec(300,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(120,View.MeasureSpec.EXACTLY));c.layout(0,0,300,120);Bitmap b=Bitmap.createBitmap(300,120,Bitmap.Config.ARGB_8888);c.draw(new Canvas(b));int valueInk=0,needleInValue=0;for(int y=87;y<105;y++)for(int x=12;x<288;x++){if(b.getPixel(x,y)==VisualButton.ink(ctx))valueInk++;if(b.getPixel(x,y)==0xff4688d4)needleInValue++;}assertTrue("Actual number must remain visible below gauge, pixels="+valueInk,valueInk>25);assertEquals("Needle must not overlap value band",0,needleInValue);String out=System.getenv("POCKET_GAUGE_PREVIEW_DIR");if(out!=null){java.nio.file.Files.createDirectories(java.nio.file.Paths.get(out));try(java.io.OutputStream s=java.nio.file.Files.newOutputStream(java.nio.file.Paths.get(out,"compact-gauge-HOST-SYNTHETIC.png"))){b.compress(Bitmap.CompressFormat.PNG,100,s);}}}
}
